```javascript
function advance() {
    return randint(0, 3) + randint(0, 3);
}

let a = randint(0, 1) + randint(0, 1);
if (flip(0.65)) {
    a += 2;
} else {
    if (a > 1) {
        a += randint(0, 1);
    }
    if (a <= 1 || flip(0.7)) {
        a += 2;
    } else if (a > 1 || flip(0.95)) {
        a = 4;
    }
}
let y = advance();
if (y === 5) {
    y = choice([1, 8], [1, 2]);
    if (a === 3) {
        y += 2;
        a += randint(0, 1);
    } else {
        y -= 1;
    }
} else if (y < a) {
    a += randint(0, 1);
    if (flip(0.8)) {
        a += 2;
    } else if (flip(0.9)) {
        y += randint(0, 1);
        a -= 1;
    }
} else {
    y += 1;
    if (flip(0.55)) {
        y -= 1;
    } else {
        a += 2;
        y += randint(0, 1);
    }
}
let steps = 0;
for (let it = 0; it < 4; it++) {
    if (a === it || y <= 4) {
        steps += 1;
    }
    if (flip(0.05)) {
